mapper.select:
SELECT EXISTS (
    SELECT 1 FROM follows WHERE follower_id = #{followerId} AND following_id = #{followingId}
)

SELECT COUNT(*)
FROM follows f JOIN users u ON u.id = f.follower_id AND u.status = 'ACTIVE'
WHERE f.following_id = #{userId}

SELECT COUNT(*)
FROM follows f JOIN users u ON u.id = f.following_id AND u.status = 'ACTIVE'
WHERE f.follower_id = #{userId}

SELECT u.id, u.nickname, u.level, f.created_at AS followed_at
FROM follows f JOIN users u ON u.id = f.follower_id AND u.status = 'ACTIVE'
WHERE f.following_id = #{userId}
ORDER BY f.created_at DESC, u.id DESC
LIMIT #{size} OFFSET #{offset}

SELECT u.id, u.nickname, u.level, f.created_at AS followed_at
FROM follows f JOIN users u ON u.id = f.following_id AND u.status = 'ACTIVE'
WHERE f.follower_id = #{userId}
ORDER BY f.created_at DESC, u.id DESC
LIMIT #{size} OFFSET #{offset}
